;; curriculum: Algebra-2 / Precalc bridge (gr 10–11) — Riemann sums; prerequisites: valley, ramp
;; math target: the bars estimate area under a curve: area ≈ Σ Δx·f(x).

app riya-level-gallery "1.1.0"
"riya level 11 · The Gallery — Riemann sums and area estimation. Walk the bar skyline, watch the area shade grow behind you, then choose the right estimate at the gate. Catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the function and the accumulating area stay visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaGalleryOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaGalleryBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaGalleryPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaGalleryFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaGalleryCurveSample = {
    x : number!
    y : number!
  }
  type RiyaGalleryCurve = {
    label : string
    color : string
    samples : [RiyaGalleryCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaGalleryGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaGalleryPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaGalleryChoiceOption = {
    id : string!
    dx : number!
    label : string!
    correct : boolean!
  }
  type RiyaGalleryChoiceGate = {
    id : string!
    x : number!
    y : number!
    hint : string
    options : [RiyaGalleryChoiceOption]!
  }
  type RiyaGalleryFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaGalleryState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaGalleryBody = { x: -9, y: 5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaGalleryPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaGalleryFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "gallery"
    platforms : [RiyaGalleryPlatform] = []
    curves : [RiyaGalleryCurve] = []
    guides : [RiyaGalleryGuide] = []
    choiceGates : [RiyaGalleryChoiceGate] = []
  }

  entity GalleryTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait GalleryBody = Body.traits.PlatformerBody -> RiyaGalleryState {
    events {
      STEER: GALLERY_STEER
      JUMP: GALLERY_LEAP
      PLACE: GALLERY_PLACE
      RESTART: GALLERY_RESTART
      CURVE_MOD_ADD: GALLERY_CURVE_MOD_ADD
      SET_TUNING: GALLERY_SET_TUNING
      SET_PLATFORMS: GALLERY_SET_PLATFORMS
      SET_SKATE_CURVE: GALLERY_SET_SKATE_CURVE
      BODY_JUMPED: GALLERY_JUMPED
      BODY_LANDED: GALLERY_LANDED
      BODY_HAZARD: GALLERY_HAZARD
      BODY_GOAL: GALLERY_GOAL
      BODY_FELL: GALLERY_FELL
      BODY_SKATE_START: GALLERY_SKATE_ON
      BODY_SKATE_END: GALLERY_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }

    listens {
      STEER { dir : number! }
      JUMP { id : string }
      PLACE { x : number!, y : number! }
      CURVE_MOD_ADD { x0 : number!, x1 : number!, a : number!, b : number, h : number!, k : number! }
      CURVE_MOD_CLEAR { }
      CURVE_MOD_CLEAR_RANGE { x0 : number!, x1 : number! }
      SET_TUNING { jumpStrength : number, moveSpeed : number, gravity : number }
      SET_PLATFORMS { platforms : [PlatformerPlatform]! }
      SET_SKATE_CURVE { curve : [PlatformerCurveSample]! }
      SET_DRIFT_REGIONS { regions : [BodyDriftRegion]! }
      RESTART { id : string }
      GalleryChallenge.GALLERY_PLACE -> GALLERY_PLACE
      RiyaGalleryPlay.GALLERY_LEAP -> GALLERY_LEAP
      RiyaGalleryPlay.GALLERY_PLACE -> GALLERY_PLACE
      RiyaGalleryPlay.GALLERY_RESTART -> GALLERY_RESTART
      RiyaGalleryPlay.GALLERY_SET_PLATFORMS -> GALLERY_SET_PLATFORMS
      RiyaGalleryPlay.GALLERY_SET_SKATE_CURVE -> GALLERY_SET_SKATE_CURVE
      RiyaGalleryPlay.GALLERY_STEER -> GALLERY_STEER
    }
  }

  trait GalleryGate = Gate.traits.ObjectiveFlow -> RiyaGalleryState {
    events {
      PROGRESS: GALLERY_PROGRESS
      GAME_END: GALLERY_GAME_END
      RESTART: GALLERY_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaGalleryPlay.GALLERY_PROGRESS -> GALLERY_PROGRESS
      RiyaGalleryPlay.GALLERY_RESTART -> GALLERY_RESTART
    }
  }

  trait GalleryFx = Particles.traits.FxParticles -> RiyaGalleryState {
    events {
      BURST: GALLERY_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      GalleryChallenge.GALLERY_BURST -> GALLERY_BURST
      RiyaGalleryPlay.GALLERY_BURST -> GALLERY_BURST
    }
  }

  trait GalleryLevelData -> @rebindable RiyaGalleryState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "gallery"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          choiceGates: (array/map @config.choiceGates (fn g @g))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaGalleryPlatform]!
        stars : [RiyaGalleryPickup]!
        skateCurve : [RiyaGalleryCurveSample]
        curveOverlay : [RiyaGalleryCurve]
        guides : [RiyaGalleryGuide]
        choiceGates : [RiyaGalleryChoiceGate]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Gallery"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 3 + 2·sin(x/2)"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the bars are a Riemann sum; the shaded region under the curve is the integral; choose the estimate that matches the shaded area"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 4.9
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of bar b0); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 3.7
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of bar b9, the last skyline bar before the choice gate); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaGalleryPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 6.9, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 5.9, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 4.3, type: "ground" }
