  trait GalleryPickup = Pickup.traits.Pickup -> RiyaGalleryState {
    events {
      PICKED: GALLERY_PICKED
      COLLECT: GALLERY_COLLECT
      PICKUP_SET_COMPLETED: GALLERY_PICKUP_SET_COMPLETED
      SET_FEATURES: GALLERY_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }

    listens {
      BODY_MOVED { x : number!, y : number!, vx : number!, vy : number!, grounded : boolean!, skating : boolean!, speed : number! }
      SET_FEATURES { features : [PickupFeature]! }
      ADD_FEATURES { features : [PickupFeature]! }
      FEATURES_ACTIVE { updates : [PickupActiveUpdate]! }
      RESTART { id : string }
      GalleryBody.BODY_MOVED -> BODY_MOVED
      RiyaGalleryPlay.GALLERY_SET_FEATURES -> GALLERY_SET_FEATURES
    }
  }

