  trait RiyaGalleryPlay -> @rebindable RiyaGalleryState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit GALLERY_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "GALLERY_LEFT", KeyA: "GALLERY_LEFT", ArrowRight: "GALLERY_RIGHT", KeyD: "GALLERY_RIGHT", ArrowUp: "GALLERY_JUMP", KeyW: "GALLERY_JUMP", Space: "GALLERY_JUMP" }
            keyUpMap: { ArrowLeft: "GALLERY_STOP", KeyA: "GALLERY_STOP", ArrowRight: "GALLERY_STOP", KeyD: "GALLERY_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: (if (== (object/get @p type) "hazard") "#ef4444" @config.terrainColor), opacity: 0.85 }))
            regions: [ {
              samples: (array/concat
                (array/filter (object/get (array/first @entity.curves) samples) (fn s (<= (object/get @s x) (+ @entity.body.x 0.3))))
                [ { x: (+ @entity.body.x 0.3), y: 0 } ]),
              baseline: 0,
              color: "#3b82f6",
              opacity: 0.18,
              label: "∫f"
            } ]
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                (array/map @entity.choiceGates (fn g
                  (array/map (object/get @g options) (fn o
                    { x: (+ (object/get @g x) (object/get @o dx)), y: (+ (object/get @g y) 0.4), label: (object/get @o label), color: (if (== (object/get @o correct) true) "#22c55e" "#ef4444"), radius: 10 }))))
                (array/concat
                  [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                  (array/concat
                    (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "GALLERY_LEFT", right: "GALLERY_RIGHT", up: "GALLERY_JUMP" }, directionReleaseEvents: { left: "GALLERY_STOP", right: "GALLERY_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "gallery")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.choiceGates @payload.choiceGates)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit GALLERY_SET_PLATFORMS { platforms: @payload.platforms })
        (emit GALLERY_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit GALLERY_SET_FEATURES { features: @payload.stars })

      GALLERY_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GALLERY_STEER { dir: -1 })

      GALLERY_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GALLERY_STEER { dir: 1 })

      GALLERY_STOP -> idle when (== @entity.active true)
        (emit GALLERY_STEER { dir: 0 })

      GALLERY_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GALLERY_LEAP {})

      GALLERY_FELL -> idle when (== @entity.active true)
        (emit GALLERY_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit GALLERY_BURST { particles: (array/map [ "fx-gallery-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      GALLERY_SKATE_ON -> idle when (== @entity.active true)
        (emit GALLERY_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "this strip adds to the total", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-gallery-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      GALLERY_PICKED -> idle when (== @entity.active true)
        (emit GALLERY_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (if (== @payload.kind "star") @payload.glyph @payload.message), ttl: 2 })) })
      GALLERY_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit GALLERY_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      GALLERY_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit GALLERY_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "area ≈ Σ Δx·f(x)", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit GALLERY_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      GALLERY_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "gallery" })

      GALLERY_TUTORIAL_DONE -> idle
        (emit GALLERY_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "each bar is width × height = Δx·f(x)", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "GALLERY_LEFT", KeyA: "GALLERY_LEFT", ArrowRight: "GALLERY_RIGHT", KeyD: "GALLERY_RIGHT", ArrowUp: "GALLERY_JUMP", KeyW: "GALLERY_JUMP", Space: "GALLERY_JUMP" }
            keyUpMap: { ArrowLeft: "GALLERY_STOP", KeyA: "GALLERY_STOP", ArrowRight: "GALLERY_STOP", KeyD: "GALLERY_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: (if (== (object/get @p type) "hazard") "#ef4444" @config.terrainColor), opacity: 0.85 }))
            regions: [ {
              samples: (array/concat
                (array/filter (object/get (array/first @entity.curves) samples) (fn s (<= (object/get @s x) (+ @entity.body.x 0.3))))
                [ { x: (+ @entity.body.x 0.3), y: 0 } ]),
              baseline: 0,
              color: "#3b82f6",
              opacity: 0.18,
              label: "∫f"
            } ]
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                (array/map @entity.choiceGates (fn g
                  (array/map (object/get @g options) (fn o
                    { x: (+ (object/get @g x) (object/get @o dx)), y: (+ (object/get @g y) 0.4), label: (object/get @o label), color: (if (== (object/get @o correct) true) "#22c55e" "#ef4444"), radius: 10 }))))
                (array/concat
                  [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                  (array/concat
                    (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      GALLERY_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      GALLERY_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
