  trait GalleryChallenge -> @rebindable RiyaGalleryState [game-core, instance] {
    initial: idle

    state idle {
      GALLERY_HAZARD -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (emit GALLERY_PLACE { x: -9, y: 5 })
        (emit GALLERY_BURST { particles: (array/map [ "fx-gallery-hazard" ] (fn fid { id: @fid, type: "info", x: -9, z: 5, message: "✗", ttl: 3 })) })

      GALLERY_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (== @payload.kind "sample")
          (emit GALLERY_BURST { particles: (array/map [ "narrative-sample" ] (fn fid { id: @fid, type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: "Δx·f(x)", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
          null)
    }

    emits {
      GALLERY_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the wrong-choice hazard respawn teleport."
        @tier "domain"
      GALLERY_BURST -> external {
        particles : [RiyaGalleryFx]
      }
        @description "Particle batch spawned on the sample-pad pickup or the hazard respawn; fx-particles fades it."
        @tier "domain"
    }

    listens {
      GalleryBody.GALLERY_HAZARD -> GALLERY_HAZARD
      GalleryPickup.GALLERY_PICKED -> GALLERY_PICKED
      GALLERY_HAZARD { id : string! }
      GALLERY_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "gallery"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaGalleryClear -> @rebindable RiyaGalleryState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "GALLERY_NEXT", variant: "primary" } ]
        })

      GALLERY_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RiyaGalleryPlay.RIYA_LEVEL_SOLVED -> RIYA_LEVEL_SOLVED
      RIYA_LEVEL_SOLVED { level : string }
      GALLERY_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-gallery"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Gallery clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You walked across the whole area under the curve, bar by bar."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-gallery" as RiyaGalleryPage -> GalleryLevelData, GalleryBody, GalleryGate, GalleryFx, GalleryPickup, GalleryTutorial, RiyaGalleryGenre, RiyaGalleryPlay, GalleryChallenge, RiyaGalleryClear
